param([Parameter(Mandatory)][string]$ServiceId,[Parameter(Mandatory)][string]$WinSwBinaryFile,[Parameter(Mandatory)][string]$PowerShellExecutable,
    [Parameter(Mandatory)][string]$SupervisorLauncherFile,[Parameter(Mandatory)][string]$SupervisorConfigurationFile,[Parameter(Mandatory)][string]$SupervisorConfigurationSignatureFile,
    [Parameter(Mandatory)][string]$SupervisorConfigurationPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedSupervisorConfigurationKeyId,
    [Parameter(Mandatory)][string]$ReleaseSigningPublicKeyFile,[Parameter(Mandatory)][string]$HostManifestPrivateKeyFile,[Parameter(Mandatory)][string]$HostManifestKeyId,
    [Parameter(Mandatory)][string]$WorkingDirectory,[Parameter(Mandatory)][string]$LogDirectory,[Parameter(Mandatory)][string]$OutputDirectory,
    [switch]$TestOnlyPackage,[string]$TestOnlyExpectedWinSwSha256)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";$expectedWinSw='05b82d46ad331cc16bdc00de5c6332c1ef818df8ceefcd49c726553209b3a0da'
if($TestOnlyPackage){if($TestOnlyExpectedWinSwSha256-notmatch'^[a-f0-9]{64}$'){throw 'Test-only WinSW hash is invalid'};$expectedWinSw=$TestOnlyExpectedWinSwSha256}
if($ServiceId-notmatch'^[A-Za-z][A-Za-z0-9._-]{2,63}$'){throw 'Windows service id is invalid'}
$paths=@{};foreach($entry in @{WinSw=$WinSwBinaryFile;PowerShell=$PowerShellExecutable;Launcher=$SupervisorLauncherFile;Configuration=$SupervisorConfigurationFile;ConfigurationSignature=$SupervisorConfigurationSignatureFile}.GetEnumerator()){$path=[IO.Path]::GetFullPath($entry.Value);if(-not(Test-Path $path -PathType Leaf)){throw "$($entry.Key) file does not exist"};if(-not$TestOnlyPackage){Assert-BackupPathOutsideRepository $path $entry.Key|Out-Null};$paths[$entry.Key]=$path}
if((Get-FileHash $paths.WinSw -Algorithm SHA256).Hash.ToLowerInvariant()-cne$expectedWinSw){throw 'WinSW binary hash is not approved'}
$configBytes=[IO.File]::ReadAllBytes($paths.Configuration);Test-BackupSignature $configBytes ([IO.File]::ReadAllBytes($paths.ConfigurationSignature)) $SupervisorConfigurationPublicKeyFile 'Supervisor configuration'
$config=[Text.Encoding]::UTF8.GetString($configBytes)|ConvertFrom-Json -Depth 20 -DateKind String;if($config.Product-cne'ET.Server'-or$config.ArtifactType-cne'ServerSupervisorConfiguration'-or$config.SignerKeyId-cne$ExpectedSupervisorConfigurationKeyId-or$config.ServiceId-cne$ServiceId){throw 'Signed supervisor configuration identity is invalid'}
$hostFingerprint=Get-BackupKeyFingerprint $HostManifestPrivateKeyFile 'Service host manifest' $true;$supervisor=Get-BackupKeyFingerprint $SupervisorConfigurationPublicKeyFile 'Supervisor configuration' $false;$release=Get-BackupKeyFingerprint $ReleaseSigningPublicKeyFile 'Release signer' $false;if(@(@($hostFingerprint,$supervisor,$release)|Select-Object -Unique).Count-ne3){throw 'Service host, supervisor configuration and release signing roles are not separated'}
$work=Assert-BackupPathOutsideRepository $WorkingDirectory 'WorkingDirectory';$logs=Assert-BackupPathOutsideRepository $LogDirectory 'LogDirectory';New-Item -ItemType Directory $work,$logs -Force|Out-Null;$output=Assert-BackupPathOutsideRepository $OutputDirectory 'OutputDirectory';New-Item -ItemType Directory $output -Force|Out-Null
$xmlFile=Join-Path $output "$ServiceId.xml";$manifestFile=Join-Path $output "$ServiceId.service-host.json";if((Test-Path $xmlFile)-or(Test-Path $manifestFile)-or(Test-Path "$manifestFile.sig")){throw 'Windows service host artifact already exists'}
$doc=[Xml]'<service />';function Add-Element([string]$Name,[string]$Value){$node=$doc.CreateElement($Name);$node.InnerText=$Value;$doc.DocumentElement.AppendChild($node)|Out-Null};Add-Element id $ServiceId;Add-Element name "ET Server Supervisor ($ServiceId)";Add-Element description 'Signed ET server A/B slot supervisor';Add-Element executable $paths.PowerShell;Add-Element arguments ("-NoLogo -NoProfile -NonInteractive -File `"$($paths.Launcher)`" -ConfigurationFile `"$($paths.Configuration)`" -ConfigurationSignatureFile `"$($paths.ConfigurationSignature)`" -TrustedPublicKeyFile `"$([IO.Path]::GetFullPath($SupervisorConfigurationPublicKeyFile))`" -ExpectedSigningKeyId `"$ExpectedSupervisorConfigurationKeyId`"");Add-Element workingdirectory $work;Add-Element logpath $logs;Add-Element startmode 'Automatic';Add-Element delayedAutoStart 'true';Add-Element stoptimeout '60 sec';Add-Element preshutdownTimeout '3 min';Add-Element resetfailure '1 hour';Add-Element hidewindow 'true';$account=$doc.CreateElement('serviceaccount');foreach($pair in @(@('username',"NT SERVICE\$ServiceId"),@('allowservicelogon','true'))){$n=$doc.CreateElement($pair[0]);$n.InnerText=$pair[1];$account.AppendChild($n)|Out-Null};$doc.DocumentElement.AppendChild($account)|Out-Null;foreach($pair in @(@('restart','10 sec'),@('restart','30 sec'),@('none',$null))){$n=$doc.CreateElement('onfailure');$n.SetAttribute('action',$pair[0]);if($pair[1]){$n.SetAttribute('delay',$pair[1])};$doc.DocumentElement.AppendChild($n)|Out-Null};$settings=[Xml.XmlWriterSettings]::new();$settings.Encoding=[Text.UTF8Encoding]::new($false);$settings.Indent=$true;$writer=[Xml.XmlWriter]::Create($xmlFile,$settings);try{$doc.Save($writer)}finally{$writer.Dispose()}
$manifest=[ordered]@{SchemaVersion=1;Product='ET.Server';ArtifactType='WindowsServiceHostManifest';TestOnly=[bool]$TestOnlyPackage;ServiceId=$ServiceId;ServiceAccount="NT SERVICE\$ServiceId";CreatedAtUtc=[DateTimeOffset]::UtcNow.ToString('O');HostManifestKeyId=$HostManifestKeyId;HostManifestPublicKeySha256=$hostFingerprint;SupervisorConfigurationKeyId=$ExpectedSupervisorConfigurationKeyId;SupervisorConfigurationPublicKeySha256=$supervisor;ReleaseSigningPublicKeySha256=$release;ExpectedWinSwSha256=$expectedWinSw;Files=[ordered]@{WinSw=$paths.WinSw;WinSwSha256=(Get-FileHash $paths.WinSw -Algorithm SHA256).Hash.ToLowerInvariant();PowerShell=$paths.PowerShell;PowerShellSha256=(Get-FileHash $paths.PowerShell -Algorithm SHA256).Hash.ToLowerInvariant();Launcher=$paths.Launcher;LauncherSha256=(Get-FileHash $paths.Launcher -Algorithm SHA256).Hash.ToLowerInvariant();SupervisorConfiguration=$paths.Configuration;SupervisorConfigurationSha256=(Get-FileHash $paths.Configuration -Algorithm SHA256).Hash.ToLowerInvariant();SupervisorConfigurationSignature=$paths.ConfigurationSignature;SupervisorConfigurationSignatureSha256=(Get-FileHash $paths.ConfigurationSignature -Algorithm SHA256).Hash.ToLowerInvariant();ServiceXml=$xmlFile;ServiceXmlSha256=(Get-FileHash $xmlFile -Algorithm SHA256).Hash.ToLowerInvariant()}}
$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($manifest|ConvertTo-Json -Depth 10));try{[IO.File]::WriteAllBytes($manifestFile,$bytes);[IO.File]::WriteAllBytes("$manifestFile.sig",(New-BackupSignature $bytes $HostManifestPrivateKeyFile 'Service host manifest'));[ordered]@{Passed=$true;ManifestFile=$manifestFile;ServiceXml=$xmlFile;ServiceId=$ServiceId;ManifestSha256=(Get-FileHash $manifestFile -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json}catch{foreach($path in @($xmlFile,$manifestFile,"$manifestFile.sig")){if(Test-Path $path){Remove-Item $path -Force}};throw}
